use super::kit::*;
pub fn commands()->Vec<Command>{vec![Command{name:"generate_lut_node",description:"Bake an explicit pointwise/native OCIO chain to a persisted inline .cube grade node (17/33 grid), with measured interpolation error. No file dependency, no auto domain inference. Clip OR shared_graph_id target, optional parent defaults input; output not auto selected. Spatial chains rejected.",mutates:true,schema:obj(vec![("clip_id",s("clip target OR shared_graph_id")),("shared_graph_id",s("shared target OR clip_id")),("node_id",s("unique node identity")),("parent",s("input or existing node")),("steps",json!({"type":"array","items":{"type":"object"}})),("size",json!({"type":"integer","enum":[17,33]})),("time",n("frozen chain sample time")),("domain_min",json!({"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3})),("domain_max",json!({"type":"array","items":{"type":"number"},"minItems":3,"maxItems":3}))],&["node_id","steps","size"]),run:|ss,a|{
 let steps:Vec<crate::color::bake::Step>=serde_json::from_value(a.get("steps").ok_or("steps required")?.clone()).map_err(|e|e.to_string())?;let size=a.get("size").and_then(Value::as_u64).filter(|v|[17,33].contains(v)).ok_or("size17/33 required")? as usize;let domain=|k:&str,d:[f32;3]|->Result<[f32;3],String>{match a.get(k){None=>Ok(d),Some(v)=>serde_json::from_value(v.clone()).map_err(|e|e.to_string())}};
 let chain=crate::color::bake::Chain::new(steps,opt_num(a,"time",0.))?;let lut=chain.bake(size,domain("domain_min",[0.;3])?,domain("domain_max",[1.;3])?)?;let approximation=chain.error_metrics(&lut)?;
 let mut text=format!("LUT_3D_SIZE {}\nDOMAIN_MIN {} {} {}\nDOMAIN_MAX {} {} {}\n",size,lut.min[0],lut.min[1],lut.min[2],lut.max[0],lut.max[1],lut.max[2]);use std::fmt::Write;for row in &lut.data{writeln!(text,"{:.9} {:.9} {:.9}",row[0],row[1],row[2]).map_err(|e|e.to_string())?;}let serialized=crate::color::lut::Lut::parse(&text)?;let serialized_error=chain.error_metrics(&serialized)?;
 let id=str_arg(a,"node_id")?.to_string();let parent=a.get("parent").and_then(Value::as_str).unwrap_or("input").to_string();let target=match(a.get("clip_id").and_then(Value::as_str),a.get("shared_graph_id").and_then(Value::as_str)){(Some(c),None)=>(Some(c.to_string()),None),(None,Some(g))=>(None,Some(g.to_string())),_=>return Err("choose exactly clip_id OR shared_graph_id".into())};let mut g=if let Some(c)=&target.0{ss.project.find_clip_mut(c).ok_or("no clip")?.grade_graph.clone().unwrap_or_default()}else{ss.project.grade_scopes.graphs.get(target.1.as_ref().unwrap()).ok_or("missing shared graph")?.clone()};if id=="input"||g.nodes.contains_key(&id){return Err("duplicate/reserved node identity".into())}
 let n=crate::color::node_graph::Node{id:id.clone(),kind:"grade".into(),inputs:vec![parent],weights:vec![crate::keyframe::Prop::new(1.)],effect:Some(crate::model::Effect{id:id.clone(),kind:"lut".into(),params:Default::default(),strings:std::collections::BTreeMap::from([("cube_text".into(),text)])}),mask:None,bypass:false};g.nodes.insert(id.clone(),n);g.validate_project(&ss.project)?;if let Some(c)=target.0{ss.project.find_clip_mut(&c).unwrap().grade_graph=Some(g);}else{ss.project.grade_scopes.graphs.insert(target.1.unwrap(),g);}
 Ok(json!({"node_id":id,"size":size,"domain_min":lut.min,"domain_max":lut.max,"approximation":serialized_error,"float_grid_approximation":approximation,"note":"Sampled4096random+9boundary probe error, NOT all-pixel bound. Tetrahedral clamps input domain. Chain/time baked statically, original node output not auto selected."}))
}}]}
